-- 086_project_variations.sql
-- Roadmap F.31: dedicated Additional Works / Variations commercial workflow.

CREATE TABLE IF NOT EXISTS public.project_variations(
  id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,
  ontology_version_id uuid NOT NULL REFERENCES public.work_ontology_versions(id)ON DELETE RESTRICT,
  discipline_id uuid NOT NULL,work_group_id uuid NOT NULL,variation_number integer NOT NULL CHECK(variation_number>0),
  title text NOT NULL CHECK(btrim(title)<>''AND char_length(title)<=240),proposed_amount numeric(24,2)NOT NULL CHECK(proposed_amount>=0),
  approved_amount numeric(24,2)CHECK(approved_amount>=0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),
  description text NOT NULL CHECK(btrim(description)<>''AND char_length(description)<=5000),
  reason_code text NOT NULL CHECK(reason_code IN('DESIGN_CHANGE','CLIENT_REQUEST','LANDLORD_REQUIREMENT','UNFORESEEN_SITE_CONDITION','SCOPE_OMISSION','REGULATORY_REQUIREMENT','QUANTITY_INCREASE','SPECIFICATION_CHANGE','CONTRACTOR_PROPOSAL','OTHER')),
  date_identified date NOT NULL,instruction_reference text NOT NULL DEFAULT''CHECK(char_length(instruction_reference)<=1000),
  schedule_impact_days integer NOT NULL DEFAULT 0 CHECK(schedule_impact_days>=0),schedule_impact_note text NOT NULL DEFAULT''CHECK(char_length(schedule_impact_note)<=2000),
  related_activity_id bigint REFERENCES public.project_gantt_tasks(id)ON DELETE RESTRICT,
  status text NOT NULL CHECK(status IN('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','REVISION_REQUIRED')),
  rejection_reason_code text CHECK(rejection_reason_code IN('INCLUDED_IN_AWARDED_BOQ','CONTRACTOR_RESPONSIBILITY','DUPLICATE_REQUEST','NO_EVIDENCE','PRICE_NOT_ACCEPTED','NO_VALID_INSTRUCTION','OTHER')),
  review_comment text NOT NULL DEFAULT''CHECK(char_length(review_comment)<=3000),revision integer NOT NULL CHECK(revision>0),
  created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),
  submitted_at timestamptz,reviewed_by uuid REFERENCES auth.users(id)ON DELETE RESTRICT,reviewed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id,variation_number),UNIQUE(id,project_id),
  FOREIGN KEY(ontology_version_id,discipline_id,work_group_id)REFERENCES public.work_ontology_work_groups(ontology_version_id,discipline_id,id)ON DELETE RESTRICT,
  CHECK((status='APPROVED'AND approved_amount IS NOT NULL)OR(status<>'APPROVED'AND approved_amount IS NULL)),
  CHECK((status='REJECTED'AND rejection_reason_code IS NOT NULL)OR(status<>'REJECTED'AND rejection_reason_code IS NULL))
);
CREATE INDEX IF NOT EXISTS project_variations_project_status_idx ON public.project_variations(project_id,status,variation_number DESC);

CREATE TABLE IF NOT EXISTS public.project_variation_events(
  id uuid PRIMARY KEY,variation_id uuid NOT NULL,project_id bigint NOT NULL,event_type text NOT NULL CHECK(event_type IN('CREATED','UPDATED','SUBMITTED','REVIEW_STARTED','APPROVED','REJECTED','REVISION_REQUIRED')),
  from_status text,to_status text NOT NULL,revision integer NOT NULL,actor_id uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,
  proposed_amount numeric(24,2)NOT NULL,approved_amount numeric(24,2),reason_code text NOT NULL,rejection_reason_code text,comment text NOT NULL DEFAULT'',created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(variation_id,project_id)REFERENCES public.project_variations(id,project_id)ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS public.project_variation_evidence_upload_intents(
  id uuid PRIMARY KEY,variation_id uuid NOT NULL,project_id bigint NOT NULL,actor_id uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,
  client_request_id uuid NOT NULL,storage_path text NOT NULL UNIQUE,original_filename text NOT NULL CHECK(btrim(original_filename)<>''),
  mime_type text NOT NULL CHECK(mime_type IN('image/jpeg','image/png','image/webp','application/pdf')),byte_size bigint NOT NULL CHECK(byte_size>0 AND byte_size<=20971520),
  note text NOT NULL DEFAULT''CHECK(char_length(note)<=1000),expires_at timestamptz NOT NULL,registered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(actor_id,client_request_id),FOREIGN KEY(variation_id,project_id)REFERENCES public.project_variations(id,project_id)ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS public.project_variation_evidence(
  id uuid PRIMARY KEY,variation_id uuid NOT NULL,project_id bigint NOT NULL,storage_path text NOT NULL UNIQUE,
  original_filename text NOT NULL,mime_type text NOT NULL,byte_size bigint NOT NULL,note text NOT NULL DEFAULT'',
  created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(variation_id,project_id)REFERENCES public.project_variations(id,project_id)ON DELETE RESTRICT
);

ALTER TABLE public.project_variations ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_variation_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.project_variation_evidence_upload_intents ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_variation_evidence ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS project_variations_select ON public.project_variations;CREATE POLICY project_variations_select ON public.project_variations FOR SELECT TO authenticated USING(public.can_access_project(project_id));
DROP POLICY IF EXISTS project_variation_events_select ON public.project_variation_events;CREATE POLICY project_variation_events_select ON public.project_variation_events FOR SELECT TO authenticated USING(public.can_access_project(project_id));
DROP POLICY IF EXISTS project_variation_intents_select ON public.project_variation_evidence_upload_intents;CREATE POLICY project_variation_intents_select ON public.project_variation_evidence_upload_intents FOR SELECT TO authenticated USING(actor_id=auth.uid());
DROP POLICY IF EXISTS project_variation_evidence_select ON public.project_variation_evidence;CREATE POLICY project_variation_evidence_select ON public.project_variation_evidence FOR SELECT TO authenticated USING(public.can_access_project(project_id));
REVOKE ALL ON TABLE public.project_variations,public.project_variation_events,public.project_variation_evidence_upload_intents,public.project_variation_evidence FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON TABLE public.project_variations,public.project_variation_events,public.project_variation_evidence TO authenticated;

INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)VALUES('variation-evidence','variation-evidence',false,20971520,ARRAY['image/jpeg','image/png','image/webp','application/pdf'])ON CONFLICT(id)DO UPDATE SET public=false,file_size_limit=EXCLUDED.file_size_limit,allowed_mime_types=EXCLUDED.allowed_mime_types;
DROP POLICY IF EXISTS variation_evidence_files_read ON storage.objects;CREATE POLICY variation_evidence_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='variation-evidence'AND(EXISTS(SELECT 1 FROM public.project_variation_evidence e WHERE e.storage_path=name AND public.can_access_project(e.project_id))OR EXISTS(SELECT 1 FROM public.project_variation_evidence_upload_intents i WHERE i.storage_path=name AND i.actor_id=auth.uid()AND i.registered_at IS NULL)));
DROP POLICY IF EXISTS variation_evidence_files_upload ON storage.objects;CREATE POLICY variation_evidence_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='variation-evidence'AND EXISTS(SELECT 1 FROM public.project_variation_evidence_upload_intents i WHERE i.storage_path=name AND i.actor_id=auth.uid()AND i.registered_at IS NULL AND i.expires_at>now()));
DROP POLICY IF EXISTS variation_evidence_files_abandon ON storage.objects;CREATE POLICY variation_evidence_files_abandon ON storage.objects FOR DELETE TO authenticated USING(bucket_id='variation-evidence'AND EXISTS(SELECT 1 FROM public.project_variation_evidence_upload_intents i WHERE i.storage_path=name AND i.actor_id=auth.uid()AND i.registered_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.project_variation_evidence e WHERE e.storage_path=name)));

CREATE OR REPLACE FUNCTION public.get_project_variation_workspace(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_project public.projects%ROWTYPE;v_role text;v_currency text;v_scope jsonb;v_rows jsonb;
BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION'Authentication required'USING ERRCODE='28000';END IF;SELECT *INTO v_project FROM public.projects WHERE id=p_project_id;SELECT lower(role)INTO v_role FROM public.profiles WHERE id=v_uid;
 IF v_project.id IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE OR v_role NOT IN('contractor','pm','admin')THEN RAISE EXCEPTION'VARIATION_WORKSPACE_FORBIDDEN'USING ERRCODE='42501';END IF;
 IF v_project.work_ontology_version_id IS NULL THEN RAISE EXCEPTION'PROJECT_VARIATIONS_REQUIRE_WORK_ONTOLOGY'USING ERRCODE='55000';END IF;
 SELECT COALESCE((SELECT currency_code FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1),v_project.currency_code,'USD')INTO v_currency;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('disciplineId',d.id,'disciplineCode',d.code,'disciplineLabel',d.label,'workGroupId',g.id,'workGroupCode',g.code,'workGroupLabel',g.label)ORDER BY d.display_order,g.display_order),'[]'::jsonb)INTO v_scope FROM public.work_ontology_disciplines d JOIN public.work_ontology_work_groups g ON g.ontology_version_id=d.ontology_version_id AND g.discipline_id=d.id WHERE d.ontology_version_id=v_project.work_ontology_version_id AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_project.scope->'disciplineIds')x(value)WHERE x.value::uuid=d.id);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('variationId',v.id,'variationNumber',v.variation_number,'title',v.title,'disciplineId',v.discipline_id,'workGroupId',v.work_group_id,'disciplineLabel',d.label,'workGroupLabel',g.label,'proposedAmount',v.proposed_amount,'approvedAmount',v.approved_amount,'currencyCode',v.currency_code,'description',v.description,'reasonCode',v.reason_code,'dateIdentified',v.date_identified,'instructionReference',v.instruction_reference,'scheduleImpactDays',v.schedule_impact_days,'scheduleImpactNote',v.schedule_impact_note,'relatedActivityId',v.related_activity_id,'status',v.status,'rejectionReasonCode',v.rejection_reason_code,'reviewComment',v.review_comment,'revision',v.revision,'createdBy',v.created_by,'createdAt',v.created_at,'submittedAt',v.submitted_at,'reviewedBy',v.reviewed_by,'reviewedAt',v.reviewed_at,'evidence',COALESCE((SELECT jsonb_agg(jsonb_build_object('evidenceId',e.id,'filename',e.original_filename,'mimeType',e.mime_type,'byteSize',e.byte_size,'note',e.note,'storagePath',e.storage_path,'createdAt',e.created_at)ORDER BY e.created_at)FROM public.project_variation_evidence e WHERE e.variation_id=v.id),'[]'::jsonb))ORDER BY v.variation_number DESC),'[]'::jsonb)INTO v_rows FROM public.project_variations v JOIN public.work_ontology_disciplines d ON d.ontology_version_id=v.ontology_version_id AND d.id=v.discipline_id JOIN public.work_ontology_work_groups g ON g.ontology_version_id=v.ontology_version_id AND g.id=v.work_group_id WHERE v.project_id=p_project_id;
 RETURN jsonb_build_object('projectId',p_project_id,'projectCode',v_project.store_code,'projectName',v_project.shopping_mall_name,'currencyCode',v_currency,'role',upper(v_role),'canCreate',v_role='contractor','canReview',v_role IN('pm','admin')AND public.can_write_project(p_project_id),'scope',v_scope,'activities',COALESCE((SELECT jsonb_agg(jsonb_build_object('activityId',t.id,'activityCode',t.wp_id,'activityLabel',COALESCE(t.wp_label,t.wp_id))ORDER BY t.sort_order,t.id)FROM public.project_gantt_tasks t WHERE t.project_id=p_project_id AND COALESCE(t.is_archived,false)=false),'[]'::jsonb),'summary',jsonb_build_object('draftCount',(SELECT count(*)FROM public.project_variations WHERE project_id=p_project_id AND status='DRAFT'),'newCount',(SELECT count(*)FROM public.project_variations WHERE project_id=p_project_id AND status='SUBMITTED'),'pendingCount',(SELECT count(*)FROM public.project_variations WHERE project_id=p_project_id AND status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED')),'approvedCount',(SELECT count(*)FROM public.project_variations WHERE project_id=p_project_id AND status='APPROVED'),'rejectedCount',(SELECT count(*)FROM public.project_variations WHERE project_id=p_project_id AND status='REJECTED'),'pendingExposure',COALESCE((SELECT sum(proposed_amount)FROM public.project_variations WHERE project_id=p_project_id AND status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED')),0),'approvedVariations',COALESCE((SELECT sum(approved_amount)FROM public.project_variations WHERE project_id=p_project_id AND status='APPROVED'),0)),'variations',v_rows);
END;$$;

CREATE OR REPLACE FUNCTION public.save_project_variation(p_project_id bigint,p_variation_id uuid,p_discipline_id uuid,p_work_group_id uuid,p_title text,p_proposed_amount numeric,p_description text,p_reason_code text,p_date_identified date,p_instruction_reference text,p_schedule_impact_days integer,p_schedule_impact_note text,p_related_activity_id bigint,p_expected_revision integer,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_project public.projects%ROWTYPE;v_existing public.project_variations%ROWTYPE;v_request public.write_command_requests%ROWTYPE;v_number integer;v_revision integer;v_result jsonb;v_currency text;v_event text;
BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION'Authentication required'USING ERRCODE='28000';END IF;
 IF p_variation_id IS NULL OR p_client_request_id IS NULL OR p_expected_revision<0 OR btrim(COALESCE(p_title,''))=''OR char_length(p_title)>240 OR p_proposed_amount<0 OR btrim(COALESCE(p_description,''))=''OR char_length(p_description)>5000 OR p_reason_code NOT IN('DESIGN_CHANGE','CLIENT_REQUEST','LANDLORD_REQUIREMENT','UNFORESEEN_SITE_CONDITION','SCOPE_OMISSION','REGULATORY_REQUIREMENT','QUANTITY_INCREASE','SPECIFICATION_CHANGE','CONTRACTOR_PROPOSAL','OTHER')OR p_date_identified IS NULL OR char_length(COALESCE(p_instruction_reference,''))>1000 OR p_schedule_impact_days<0 OR char_length(COALESCE(p_schedule_impact_note,''))>2000 THEN RAISE EXCEPTION'INVALID_VARIATION_COMMAND'USING ERRCODE='22023';END IF;
 SELECT *INTO v_project FROM public.projects WHERE id=p_project_id;IF lower((SELECT role FROM public.profiles WHERE id=v_uid))<>'contractor'OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'VARIATION_SUBMISSION_FORBIDDEN'USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.work_ontology_work_groups g WHERE g.ontology_version_id=v_project.work_ontology_version_id AND g.discipline_id=p_discipline_id AND g.id=p_work_group_id AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_project.scope->'disciplineIds')x(value)WHERE x.value::uuid=p_discipline_id))THEN RAISE EXCEPTION'VARIATION_WORK_GROUP_OUTSIDE_PROJECT_SCOPE'USING ERRCODE='22023';END IF;
 IF p_related_activity_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.project_gantt_tasks WHERE id=p_related_activity_id AND project_id=p_project_id)THEN RAISE EXCEPTION'VARIATION_ACTIVITY_PROJECT_MISMATCH'USING ERRCODE='22023';END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'variation.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='variation.save'AND client_request_id=p_client_request_id;IF v_request.response IS NOT NULL THEN RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;
 SELECT *INTO v_existing FROM public.project_variations WHERE id=p_variation_id FOR UPDATE;IF COALESCE(v_existing.revision,0)<>p_expected_revision THEN RAISE EXCEPTION'VARIATION_REVISION_CONFLICT'USING ERRCODE='40001';END IF;IF v_existing.id IS NOT NULL AND(v_existing.project_id<>p_project_id OR v_existing.created_by<>v_uid)THEN RAISE EXCEPTION'VARIATION_SUBMISSION_FORBIDDEN'USING ERRCODE='42501';END IF;IF v_existing.id IS NOT NULL AND v_existing.status NOT IN('DRAFT','REVISION_REQUIRED')THEN RAISE EXCEPTION'VARIATION_NOT_EDITABLE'USING ERRCODE='55000';END IF;
 SELECT COALESCE((SELECT currency_code FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1),v_project.currency_code,'USD')INTO v_currency;v_revision:=p_expected_revision+1;
 IF v_existing.id IS NULL THEN PERFORM pg_advisory_xact_lock(p_project_id);SELECT COALESCE(max(variation_number),0)+1 INTO v_number FROM public.project_variations WHERE project_id=p_project_id;INSERT INTO public.project_variations(id,project_id,ontology_version_id,discipline_id,work_group_id,variation_number,title,proposed_amount,currency_code,description,reason_code,date_identified,instruction_reference,schedule_impact_days,schedule_impact_note,related_activity_id,status,revision,created_by)VALUES(p_variation_id,p_project_id,v_project.work_ontology_version_id,p_discipline_id,p_work_group_id,v_number,btrim(p_title),p_proposed_amount,v_currency,btrim(p_description),p_reason_code,p_date_identified,btrim(COALESCE(p_instruction_reference,'')),p_schedule_impact_days,btrim(COALESCE(p_schedule_impact_note,'')),p_related_activity_id,'DRAFT',v_revision,v_uid);v_event:='CREATED';
 ELSE v_number:=v_existing.variation_number;UPDATE public.project_variations SET discipline_id=p_discipline_id,work_group_id=p_work_group_id,title=btrim(p_title),proposed_amount=p_proposed_amount,description=btrim(p_description),reason_code=p_reason_code,date_identified=p_date_identified,instruction_reference=btrim(COALESCE(p_instruction_reference,'')),schedule_impact_days=p_schedule_impact_days,schedule_impact_note=btrim(COALESCE(p_schedule_impact_note,'')),related_activity_id=p_related_activity_id,status='DRAFT',review_comment='',revision=v_revision,updated_at=now()WHERE id=p_variation_id;v_event:='UPDATED';END IF;
 INSERT INTO public.project_variation_events VALUES(gen_random_uuid(),p_variation_id,p_project_id,v_event,CASE WHEN v_existing.id IS NULL THEN NULL ELSE v_existing.status END,'DRAFT',v_revision,v_uid,p_proposed_amount,NULL,p_reason_code,NULL,'',now());v_result:=jsonb_build_object('variationId',p_variation_id,'variationNumber',v_number,'status','DRAFT','revision',v_revision);UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

CREATE OR REPLACE FUNCTION public.transition_project_variation(p_variation_id uuid,p_action text,p_approved_amount numeric,p_rejection_reason_code text,p_comment text,p_expected_revision integer,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v_role text;v public.project_variations%ROWTYPE;v_request public.write_command_requests%ROWTYPE;v_to text;v_event text;v_result jsonb;
BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION'Authentication required'USING ERRCODE='28000';END IF;SELECT *INTO v FROM public.project_variations WHERE id=p_variation_id FOR UPDATE;IF v.id IS NULL THEN RAISE EXCEPTION'VARIATION_NOT_FOUND'USING ERRCODE='P0002';END IF;SELECT lower(role)INTO v_role FROM public.profiles WHERE id=v_uid;
 IF p_expected_revision IS NULL OR p_expected_revision<0 OR p_client_request_id IS NULL THEN RAISE EXCEPTION'INVALID_VARIATION_TRANSITION'USING ERRCODE='22023';END IF;
 IF p_action='SUBMIT'THEN IF v_role<>'contractor'OR v.created_by<>v_uid OR public.can_access_project(v.project_id)IS NOT TRUE THEN RAISE EXCEPTION'VARIATION_SUBMIT_FORBIDDEN'USING ERRCODE='42501';END IF;
 ELSE IF v_role NOT IN('pm','admin')OR public.can_write_project(v.project_id)IS NOT TRUE THEN RAISE EXCEPTION'VARIATION_REVIEW_FORBIDDEN'USING ERRCODE='42501';END IF;END IF;
 INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(v_uid,'variation.transition',p_client_request_id,v.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO v_request FROM public.write_command_requests WHERE actor_id=v_uid AND operation='variation.transition'AND client_request_id=p_client_request_id;IF v_request.response IS NOT NULL THEN RETURN v_request.response||jsonb_build_object('idempotentReplay',true);END IF;
 IF p_expected_revision<>v.revision THEN RAISE EXCEPTION'VARIATION_REVISION_CONFLICT'USING ERRCODE='40001';END IF;
 IF p_action='SUBMIT'THEN IF v.status<>'DRAFT'THEN RAISE EXCEPTION'INVALID_VARIATION_TRANSITION'USING ERRCODE='22023';END IF;v_to:='SUBMITTED';v_event:='SUBMITTED';
 ELSE
  IF p_action='START_REVIEW'AND v.status='SUBMITTED'THEN v_to:='UNDER_REVIEW';v_event:='REVIEW_STARTED';
  ELSIF p_action='APPROVE'AND v.status IN('SUBMITTED','UNDER_REVIEW')AND p_approved_amount IS NOT NULL AND p_approved_amount>=0 THEN v_to:='APPROVED';v_event:='APPROVED';
  ELSIF p_action='REJECT'AND v.status IN('SUBMITTED','UNDER_REVIEW')AND p_rejection_reason_code IN('INCLUDED_IN_AWARDED_BOQ','CONTRACTOR_RESPONSIBILITY','DUPLICATE_REQUEST','NO_EVIDENCE','PRICE_NOT_ACCEPTED','NO_VALID_INSTRUCTION','OTHER')THEN v_to:='REJECTED';v_event:='REJECTED';
  ELSIF p_action='REQUEST_REVISION'AND v.status IN('SUBMITTED','UNDER_REVIEW')AND btrim(COALESCE(p_comment,''))<>''THEN v_to:='REVISION_REQUIRED';v_event:='REVISION_REQUIRED';ELSE RAISE EXCEPTION'INVALID_VARIATION_TRANSITION'USING ERRCODE='22023';END IF;
 END IF;
 UPDATE public.project_variations SET status=v_to,approved_amount=CASE WHEN v_to='APPROVED'THEN p_approved_amount ELSE NULL END,rejection_reason_code=CASE WHEN v_to='REJECTED'THEN p_rejection_reason_code ELSE NULL END,review_comment=btrim(COALESCE(p_comment,'')),revision=revision+1,submitted_at=CASE WHEN v_to='SUBMITTED'THEN now()ELSE submitted_at END,reviewed_by=CASE WHEN v_to IN('APPROVED','REJECTED','REVISION_REQUIRED')THEN v_uid ELSE reviewed_by END,reviewed_at=CASE WHEN v_to IN('APPROVED','REJECTED','REVISION_REQUIRED')THEN now()ELSE reviewed_at END,updated_at=now()WHERE id=v.id;
 INSERT INTO public.project_variation_events VALUES(gen_random_uuid(),v.id,v.project_id,v_event,v.status,v_to,v.revision+1,v_uid,v.proposed_amount,CASE WHEN v_to='APPROVED'THEN p_approved_amount ELSE NULL END,v.reason_code,CASE WHEN v_to='REJECTED'THEN p_rejection_reason_code ELSE NULL END,btrim(COALESCE(p_comment,'')),now());v_result:=jsonb_build_object('variationId',v.id,'status',v_to,'revision',v.revision+1,'approvedAmount',CASE WHEN v_to='APPROVED'THEN p_approved_amount ELSE NULL END);UPDATE public.write_command_requests SET response=v_result,completed_at=now()WHERE id=v_request.id;RETURN v_result||jsonb_build_object('idempotentReplay',false);
END;$$;

CREATE OR REPLACE FUNCTION public.authorize_variation_evidence_upload(p_variation_id uuid,p_request_id uuid,p_evidence_id uuid,p_filename text,p_mime_type text,p_byte_size bigint,p_note text)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_uid uuid:=auth.uid();v public.project_variations%ROWTYPE;i public.project_variation_evidence_upload_intents%ROWTYPE;v_path text;
BEGIN SELECT *INTO v FROM public.project_variations WHERE id=p_variation_id;IF v.id IS NULL THEN RAISE EXCEPTION'VARIATION_NOT_FOUND'USING ERRCODE='P0002';END IF;IF lower((SELECT role FROM public.profiles WHERE id=v_uid))<>'contractor'OR v.created_by<>v_uid OR v.status NOT IN('DRAFT','REVISION_REQUIRED')OR public.can_access_project(v.project_id)IS NOT TRUE THEN RAISE EXCEPTION'VARIATION_EVIDENCE_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_request_id IS NULL OR p_evidence_id IS NULL OR btrim(COALESCE(p_filename,''))=''OR p_mime_type NOT IN('image/jpeg','image/png','image/webp','application/pdf')OR p_byte_size<=0 OR p_byte_size>20971520 OR char_length(COALESCE(p_note,''))>1000 THEN RAISE EXCEPTION'INVALID_VARIATION_EVIDENCE_FILE'USING ERRCODE='22023';END IF;
 SELECT *INTO i FROM public.project_variation_evidence_upload_intents WHERE actor_id=v_uid AND client_request_id=p_request_id;IF i.id IS NOT NULL THEN IF i.variation_id<>p_variation_id OR i.id<>p_evidence_id THEN RAISE EXCEPTION'VARIATION_EVIDENCE_IDEMPOTENCY_CONFLICT'USING ERRCODE='23505';END IF;RETURN jsonb_build_object('bucket','variation-evidence','path',i.storage_path,'requestId',p_request_id,'evidenceId',i.id,'registered',i.registered_at IS NOT NULL);END IF;
 v_path:=v.project_id::text||'/'||v.id::text||'/'||p_evidence_id::text||CASE WHEN p_mime_type='application/pdf'THEN'.pdf'WHEN p_mime_type='image/png'THEN'.png'WHEN p_mime_type='image/webp'THEN'.webp'ELSE'.jpg'END;INSERT INTO public.project_variation_evidence_upload_intents(id,variation_id,project_id,actor_id,client_request_id,storage_path,original_filename,mime_type,byte_size,note,expires_at)VALUES(p_evidence_id,v.id,v.project_id,v_uid,p_request_id,v_path,btrim(p_filename),p_mime_type,p_byte_size,btrim(COALESCE(p_note,'')),now()+interval'30 minutes');RETURN jsonb_build_object('bucket','variation-evidence','path',v_path,'requestId',p_request_id,'evidenceId',p_evidence_id,'registered',false);
END;$$;
CREATE OR REPLACE FUNCTION public.register_variation_evidence(p_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage AS $$
DECLARE v_uid uuid:=auth.uid();i public.project_variation_evidence_upload_intents%ROWTYPE;e public.project_variation_evidence%ROWTYPE;o storage.objects%ROWTYPE;
BEGIN SELECT *INTO i FROM public.project_variation_evidence_upload_intents WHERE actor_id=v_uid AND client_request_id=p_request_id FOR UPDATE;IF i.id IS NULL THEN RAISE EXCEPTION'VARIATION_EVIDENCE_INTENT_NOT_FOUND'USING ERRCODE='P0002';END IF;IF i.registered_at IS NOT NULL THEN SELECT *INTO e FROM public.project_variation_evidence WHERE id=i.id;RETURN jsonb_build_object('evidence',to_jsonb(e),'idempotentReplay',true);END IF;IF i.expires_at<=now()THEN RAISE EXCEPTION'VARIATION_EVIDENCE_INTENT_EXPIRED'USING ERRCODE='55000';END IF;SELECT *INTO o FROM storage.objects WHERE bucket_id='variation-evidence'AND name=i.storage_path;IF o.id IS NULL THEN RAISE EXCEPTION'VARIATION_EVIDENCE_UPLOAD_MISSING'USING ERRCODE='55000';END IF;INSERT INTO public.project_variation_evidence(id,variation_id,project_id,storage_path,original_filename,mime_type,byte_size,note,created_by)VALUES(i.id,i.variation_id,i.project_id,i.storage_path,i.original_filename,i.mime_type,i.byte_size,i.note,v_uid)RETURNING *INTO e;UPDATE public.project_variation_evidence_upload_intents SET registered_at=now()WHERE id=i.id;RETURN jsonb_build_object('evidence',to_jsonb(e),'idempotentReplay',false);END;$$;

REVOKE ALL ON FUNCTION public.get_project_variation_workspace(bigint),public.save_project_variation(bigint,uuid,uuid,uuid,text,numeric,text,text,date,text,integer,text,bigint,integer,uuid),public.transition_project_variation(uuid,text,numeric,text,text,integer,uuid),public.authorize_variation_evidence_upload(uuid,uuid,uuid,text,text,bigint,text),public.register_variation_evidence(uuid)FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_project_variation_workspace(bigint),public.save_project_variation(bigint,uuid,uuid,uuid,text,numeric,text,text,date,text,integer,text,bigint,integer,uuid),public.transition_project_variation(uuid,text,numeric,text,text,integer,uuid),public.authorize_variation_evidence_upload(uuid,uuid,uuid,text,text,bigint,text),public.register_variation_evidence(uuid)TO authenticated;
REVOKE ALL ON FUNCTION public.register_variation_evidence(uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.register_variation_evidence(uuid) TO authenticated;
